<?php declare(strict_types=1); echo $view->render('components.page-hero',compact('page','e')); ?>
<section class="section"><div class="container-wide"><?php if(!$directoryAvailable):?><div class="notice" role="status">The event directory is temporarily unavailable.</div><?php elseif($events===[]):?><div class="empty-state" role="status"><h2>No events are currently published.</h2></div><?php else:?><div class="programme-grid"><?php foreach($events as $event):?><article class="programme-card"><?php if($event['banner_path']):?><img src="<?= $e($event['banner_path']) ?>" alt="" loading="lazy"><?php endif;?><div class="programme-card-top"><span><?= $e($event['type_name']) ?></span><span class="status-pill"><?= $e($event['registration_access']==='member'?'Members':'Public') ?></span></div><h2><a href="/events/<?= rawurlencode($event['slug']) ?>"><?= $e($event['title']) ?></a></h2><p><?= $e($event['event_date']) ?><?= $event['venue']?' · '.$e($event['venue']):'' ?></p></article><?php endforeach;?></div><?php endif;?></div></section>
